-- Training v2: synchronize the canonical MISKA task and learning library.
-- Existing codes are updated so production receives the same verified copy
-- and ordering as the application; KNOW-19..25 are new learning modules.

ON CONFLICT (code) DO UPDATE SET
  task_type = EXCLUDED.task_type,
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  expected_result = EXCLUDED.expected_result,
  category = EXCLUDED.category,
  material_text = EXCLUDED.material_text,
  questions = EXCLUDED.questions,
  active = EXCLUDED.active,
  sort_order = EXCLUDED.sort_order;
