INSERT INTO business_kpi.seller_task_library
  (code, task_type, title, description, expected_result, category, material_text, questions, active, sort_order)
VALUES
  ('STORE-01', 'STORE', 'Пустые места', 'Обойди торговый зал и проверь полки на пустые места. Отметь, где товар закончился или выкладка просела.', 'Список пустых мест по полкам: что закончилось и что можно пополнить из запаса.', 'магазин', NULL, NULL, true, 1),
  ('STORE-02', 'STORE', 'Ценники категории', 'Проверь ценники в назначенной категории: наличие, соответствие цене в системе, читаемость, правильное положение.', 'Все ценники на местах, цены совпадают, повреждённые заменены.', 'магазин', NULL, NULL, true, 2),
  ('STORE-03', 'STORE', 'Сроки категории', 'Проверь сроки годности товара в назначенной категории по графику контроля. Сначала смотри то, что проверяется реже.', 'Просроченного товара нет; товар со сроком ближе ⅓ до конца вынесен вперёд/отмечен.', 'магазин', NULL, NULL, true, 3),
  ('STORE-04', 'STORE', 'AWARD на полке', 'Проверь выкладку кормов AWARD: наличие основных линеек, ценники, чистоту полки, порядок по вкусам/типам.', 'Полка AWARD полная, ценники корректны, порядок восстановлен.', 'корма', NULL, NULL, true, 4),
  ('STORE-05', 'STORE', 'Влажные корма', 'Проверь полку влажных кормов: пустые места, ценники, порядок по брендам, сроки на фасадах.', 'Пустоты пополнены или зафиксированы, ценники и сроки в порядке.', 'корма', NULL, NULL, true, 5),
  ('STORE-06', 'STORE', 'Лакомства', 'Проверь полку лакомств: наличие, ценники, сроки, выкладка (висячие карманы и полки).', 'Полка лакомств в порядке, отсутствующие позиции перечислены.', 'лакомства', NULL, NULL, true, 6),
  ('STORE-07', 'STORE', 'Наполнители', 'Проверь полку наполнителей: пустые места, тяжёлые мешки в зоне доступа, ценники, порядок.', 'Полка пополнена, крупные фасоны удобно лежат, ценники корректны.', 'наполнители', NULL, NULL, true, 7),
  ('STORE-08', 'STORE', 'Паразитарка', 'Проверь товары от блох и клещей: наличие основных позиций, сроки годности, ценники, правильная зона хранения.', 'Ассортимент паразитарки в наличии, сроки и ценники проверены.', 'паразитарка', NULL, NULL, true, 8),
  ('STORE-09', 'STORE', 'Уход', 'Проверь полку средств ухода: шампуни, расчёски, когтерезы — наличие, ценники, чистота полки.', 'Полка ухода в порядке, отсутствующее перечислено.', 'уход', NULL, NULL, true, 9),
  ('STORE-10', 'STORE', 'Игрушки', 'Проверь игрушки: наличие, внешний вид упаковок, ценники, порядок в корзинах и на крючках.', 'Игрушки разложены по местам, повреждённые упаковки сняты, ценники на местах.', 'игрушки', NULL, NULL, true, 10),
  ('STORE-11', 'STORE', 'Одежда', 'Проверь одежду для животных: размерные ряды, ценники, порядок на вешалках, пустые крючки.', 'Одежда разложена по размерам, ценники корректны, пустоты зафиксированы.', 'одежда', NULL, NULL, true, 11),
  ('STORE-12', 'STORE', 'Туалеты и аксессуары', 'Проверь туалеты, лопатки, пакеты и аксессуары: наличие, ценники, порядок на полке.', 'Полка в порядке, отсутствующие позиции перечислены.', 'туалеты/аксессуары', NULL, NULL, true, 12),
  ('STORE-13', 'STORE', 'Медленный товар', 'Найди 3–5 позиций, которые двигаются медленнее всего. Проверь сроки, ценники и выкладку — возможно, товар «потерялся» на полке.', 'Список медленных позиций с примечанием: что проверено и что предложить владельцу.', 'магазин', NULL, NULL, true, 13),
  ('STORE-14', 'STORE', 'Товар дня', 'Выбери один товар дня из ассортимента. Проверь его наличие, ценник и место на полке. Будь готов рассказать о нём покупателям.', 'Товар дня выбран, полка и ценник в порядке, продавец может рассказать о товаре.', 'магазин', NULL, NULL, true, 14),
  ('STORE-15', 'STORE', 'Проверка маячков', 'Проверь назначенную группу товаров: наличие противокражных маячков и правильность установки.', 'По назначенной группе маячки установлены правильно; отклонения перечислены.', 'магазин', NULL, NULL, true, 15),
  ('STORE-16', 'STORE', 'Контроль маячков на кассе', 'Проверь соблюдение процесса снятия/деактивации маячков и их хранения на кассе.', 'Процесс на кассе соблюдается: маячки снимаются, деактивируются и хранятся правильно.', 'магазин', NULL, NULL, true, 16),
  ('KNOW-01', 'KNOWLEDGE', 'AWARD Sterilized', 'Разберись, для каких кошек подходит линейка Sterilized и чем она отличается от обычных кормов.', 'Продавец может объяснить назначение линейки и предложить её подходящей кошке.', 'корма', 'В актуальном каталоге AWARD есть корма Sterilized для взрослых стерилизованных кошек. При консультации смотри конкретную упаковку: возраст, назначение, вкус/формат и норму кормления. Не переноси свойства одной линейки на другую и не обещай лечебный или профилактический эффект, которого нет в материалах производителя.', '["Для каких кошек в актуальном каталоге предназначены позиции AWARD Sterilized?","Какие данные нужно проверить на конкретной упаковке перед консультацией?","Какого эффекта нельзя обещать, если он не указан производителем?"]'::jsonb, true, 17),
  ('KNOW-02', 'KNOWLEDGE', 'AWARD Monoprotein', 'Разберись, что такое монопротеиновый корм и кому его можно предложить.', 'Продавец может объяснить идею одного источника белка и назвать подходящую ситуацию.', 'корма', 'У AWARD есть линейка Monoprotein для взрослых кошек, включая отдельные позиции для стерилизованных кошек. Объясняй свойства только по конкретной упаковке и официальному каталогу. Если покупатель говорит об аллергии, непереносимости или симптомах, не обещай лечебный результат и предложи обсудить рацион с ветеринарным врачом. Источник для обучения: awardpetfood.ru.', '["Для каких кошек в каталоге AWARD есть позиции Monoprotein?","Где проверять свойства конкретной позиции Monoprotein?","Что делать, если покупатель связывает выбор корма с аллергией или симптомами?"]'::jsonb, true, 18),
  ('KNOW-03', 'KNOWLEDGE', 'AWARD Urinary / Veterinary Diet', 'Разберись, чем лечебные/диетические корма отличаются от обычных и как с ними работать.', 'Продавец знает границы: диетический корм назначает ветеринар, мы не подбираем лечение.', 'ветдиеты', 'AWARD выделяет Veterinary Diet в отдельную категорию ветеринарных диет и рекомендует перед применением консультироваться с ветеринарным врачом; продолжительность или смену диеты производитель также относит к решению специалиста. Продавец помогает найти нужную позицию и объясняет информацию с упаковки, но не выбирает диету вместо врача. Источник для обучения: awardpetfood.ru/diet.', '["Кто назначает ветеринарную диету?","Что продавец может рассказать о диетическом корме, а что нет?","Как вежливо направить покупателя с симптомами к ветеринару?"]'::jsonb, true, 19),
  ('KNOW-04', 'KNOWLEDGE', 'Сухой или влажный корм', 'Разберись в различиях сухого и влажного кормления и в каких случаях что предлагать.', 'Продавец может помочь покупателю выбрать формат кормления и объяснить плюсы каждого.', 'корма', 'Не существует одного формата, который продавец должен объявлять лучшим для всех животных. Сначала уточни, что питомец ест сейчас, его возраст и задачу владельца. Затем сравни конкретные сухие и влажные позиции по назначению, полнорационности, норме кормления и другим данным на упаковке. Индивидуальную лечебную схему питания определяет ветеринарный специалист.', '["Что нужно узнать о питомце до сравнения сухого и влажного корма?","Какие данные сравниваем на упаковках конкретных рационов?","Когда вопрос питания нужно передать ветеринарному специалисту?"]'::jsonb, true, 20),
  ('KNOW-05', 'KNOWLEDGE', 'Переход на новый корм', 'Разберись, как правильно переводить животное на другой корм.', 'Продавец объясняет постепенный переход и предупреждает о резкой смене корма.', 'корма', 'При смене корма не придумывай универсальный срок перехода. Покажи покупателю схему на упаковке конкретного корма или в официальной инструкции производителя и предложи следовать ей. Если у животного есть хронические заболевания, выраженные симптомы или лечебный рацион, вопрос смены корма нужно согласовать с ветеринарным врачом.', '["Где взять схему перехода на конкретный новый корм?","Почему продавец не должен придумывать универсальный срок перехода?","В каких ситуациях смену рациона нужно согласовать с ветеринарным врачом?"]'::jsonb, true, 21),
  ('KNOW-06', 'KNOWLEDGE', 'Лакомства', 'Разберись в видах лакомств и как выбрать подходящее.', 'Продавец предлагает лакомство под конкретную задачу: поощрение, чистка зубов, занятие.', 'лакомства', 'В официальном каталоге «Мнямс» лакомства разделены по форматам и задачам, в том числе есть позиции для дрессировки и для чистки зубов. Подбирай лакомство по виду животного, возрасту/размеру и назначению, указанным на упаковке. Норму и ограничения всегда бери с конкретного товара. Источник для обучения: mnyams.ru.', '["Какие задачи лакомств есть в официальном каталоге «Мнямс»?","Какие параметры животного и товара нужно проверить перед выбором?","Где смотреть норму и ограничения для конкретного лакомства?"]'::jsonb, true, 22),
  ('KNOW-07', 'KNOWLEDGE', 'Тофу или древесный наполнитель', 'Разберись, чем отличаются два типа наполнителя и в каких ситуациях какой вариант можно предложить покупателю.', 'Продавец может сравнить два типа и предложить вариант под ситуацию покупателя.', 'наполнители', 'В актуальном ассортименте Cat’s Choice тофу обозначен как растительный комкующийся наполнитель, а древесный — как впитывающий. Не сравнивай их по цене или «лучше/хуже» без конкретного товара. Спроси, какой тип лотка используется, какой наполнитель был раньше, важны ли аромат и способ уборки, затем покажи различия по упаковке. Источник для обучения: catschoice.ru.', '["Какой тип у тофу Cat’s Choice и какой у древесного наполнителя?","Что нужно спросить про лоток и предыдущий наполнитель?","Почему нельзя объявлять один тип «лучше» без понимания ситуации покупателя?"]'::jsonb, true, 23),
  ('KNOW-08', 'KNOWLEDGE', 'Выбор наполнителя', 'Научись подбирать наполнитель по потребности: комкующийся, впитывающий, силикагель, растительный.', 'Продавец задаёт 2–3 вопроса и предлагает подходящий тип наполнителя.', 'наполнители', 'В текущем каталоге Cat’s Choice есть разные типы: растительный тофу и бумажный — комкующиеся, древесный и силикагелевый — впитывающие; есть также растительная позиция с pH-индикатором. При подборе уточни привычный тип наполнителя, лоток, отношение к ароматам, объём и бюджет. Способ использования и утилизации показывай по инструкции конкретной упаковки. Источник для обучения: catschoice.ru.', '["Какие типы наполнителей сейчас есть в каталоге Cat’s Choice?","Что нужно уточнить у покупателя перед подбором наполнителя?","Где проверить способ использования и утилизации конкретного наполнителя?"]'::jsonb, true, 24),
  ('KNOW-09', 'KNOWLEDGE', 'Блохи и клещи', 'Разберись в средствах от блох и клещей: форматы, сезонность, базовые правила применения.', 'Продавец предлагает подходящий формат и направляет к ветеринару при сомнениях.', 'паразитарка', 'Для противопаразитарного средства сначала уточни вид животного и параметры, которые требует конкретная упаковка (например, возраст или вес). Не угадывай дозировку, интервал обработки и совместимость нескольких средств: показывай только инструкцию производителя. Если покупатель описывает симптомы, осложнения или просит подобрать лечение, направь к ветеринарному специалисту.', '["Какие данные о животном нужно уточнить до продажи конкретного средства?","Где брать дозировку, интервал обработки и ограничения?","В каких случаях продавец должен направить покупателя к ветеринарному специалисту?"]'::jsonb, true, 25),
  ('KNOW-10', 'KNOWLEDGE', 'Шампуни', 'Разберись в шампунях для животных: обычные, для щенков/котят, специализированные.', 'Продавец подбирает шампунь под задачу и предупреждает о моющих средствах «не для животных».', 'уход', 'Подбирай средство, которое производитель прямо предназначил для нужного вида животного, возраста и задачи. Объясняй способ применения и ограничения по упаковке. Если покупатель описывает зуд, воспаление, выпадение шерсти, раны или другую проблему кожи, не подбирай «лечебный» уход самостоятельно — рекомендуй консультацию ветеринарного врача.', '["Какие данные на упаковке средства ухода нужно проверить перед рекомендацией?","Как объяснить покупателю способ применения и ограничения?","Что делать, если покупатель описывает проблему кожи или шерсти как симптом?"]'::jsonb, true, 26),
  ('KNOW-11', 'KNOWLEDGE', 'Уход за шерстью', 'Разберись в расчёсках, колтунорезах, когтерезах и базовом груминге.', 'Продавец предлагает инструмент под тип шерсти и показывает логичное дополнение.', 'уход', 'Сначала уточни вид животного, тип и длину шерсти и задачу владельца: регулярное вычёсывание, колтуны, когти или другой уход. Подбирай инструмент по назначению производителя и размеру питомца. Не демонстрируй рискованные процедуры и не советуй обработку повреждённой кожи — для этого нужен грумер или ветеринарный специалист.', '["Что нужно узнать о шерсти и задаче владельца до выбора инструмента?","Где проверить назначение конкретной расчёски, когтереза или другого инструмента?","Какие ситуации нельзя превращать в домашнюю «процедуру по совету продавца»?"]'::jsonb, true, 27),
  ('KNOW-12', 'KNOWLEDGE', 'Игрушки для кошки', 'Разберись в игрушках для кошек: активные, интеллектуальные, мягкие, когтеточки.', 'Продавец предлагает игрушку под поведение кошки и возраст.', 'игрушки', 'При выборе игрушки для кошки уточни возраст, привычный тип игры и что уже есть дома. Сверяй размер, материалы, ограничения и необходимость присмотра по упаковке производителя. Не продавай повреждённую игрушку; отдельно предупреди о безопасном использовании, если у изделия есть мелкие детали, шнуры или другие элементы, требующие контроля владельца.', '["Что нужно узнать о кошке до выбора игрушки?","Какие параметры безопасности нужно проверить на упаковке и самом товаре?","Когда нужно отдельно напомнить владельцу о присмотре во время игры?"]'::jsonb, true, 28),
  ('KNOW-13', 'KNOWLEDGE', 'Игрушки для собаки', 'Разберись в игрушках для собак: по размеру, типу игры и жевательной нагрузке.', 'Продавец подбирает игрушку по размеру и характеру собаки.', 'игрушки', 'Для собаки уточни размер, возраст, тип игры и насколько активно она грызёт игрушки. Сверяй размер, назначение и ограничения конкретного изделия по упаковке производителя. Не обещай неразрушимость и не предлагай повреждённый товар; если производитель требует присмотра во время игры, проговори это покупателю.', '["Какие четыре вещи нужно уточнить о собаке до выбора игрушки?","Что проверить на упаковке конкретной игрушки?","Почему нельзя обещать покупателю, что игрушка «неубиваемая»?"]'::jsonb, true, 29),
  ('KNOW-14', 'KNOWLEDGE', 'Амуниция', 'Разберись в шлейках, ошейниках и поводках: посадка, размеры, безопасность.', 'Продавец помогает подобрать амуницию по размеру и предлагает примерку.', 'амуниция', 'Шлейку, ошейник и поводок подбирай по виду животного, назначению изделия и таблице размеров конкретного производителя. Покажи, какие мерки нужны именно для этой модели, и проверь посадку при примерке: амуниция не должна причинять дискомфорт или позволять питомцу легко выскользнуть. Не используй универсальные правила вместо инструкции конкретной модели.', '["По каким данным подбираем размер конкретной модели амуниции?","Что проверяем при примерке шлейки или ошейника?","Почему нельзя заменять таблицу производителя универсальным правилом?"]'::jsonb, true, 30),
  ('KNOW-15', 'KNOWLEDGE', 'Одежда', 'Разберись в одежде для собак: размеры, сезоны, кому действительно нужна.', 'Продавец подбирает одежду по размеру и объясняет, кому она нужна.', 'одежда', 'Одежду подбирай по погодной задаче владельца, размеру питомца и таблице конкретного производителя. Уточни нужные мерки, проверь, чтобы вещь не стесняла движения и не натирала, и объясни правила ухода по ярлыку. Не выдавай одежду за лечение и не обещай медицинский эффект.', '["Что нужно узнать о задаче владельца до подбора одежды?","Где смотреть необходимые мерки и размер конкретной модели?","Что нужно проверить при примерке, кроме самого размера?"]'::jsonb, true, 31),
  ('KNOW-16', 'KNOWLEDGE', 'Витамины и добавки', 'Разберись, как грамотно рассказывать о витаминах и добавках, не обещая лечебного эффекта.', 'Продавец рассказывает о добавках как о рационе/поддержке и направляет к ветеринару при целях лечения.', 'витамины/добавки', 'Рассказывай о добавке только то, что указано на упаковке и в официальных материалах производителя: состав, назначение, способ применения и ограничения. Не обещай лечение заболевания и не оценивай совместимость с лекарствами. При болезни, приёме препаратов, беременности или другой клинической ситуации направляй покупателя к ветеринарному врачу.', '["Какие сведения о добавке продавец может объяснить по официальному источнику?","Какие обещания и оценки совместимости продавец не должен давать?","В каких ситуациях покупателя нужно направить к ветеринарному врачу?"]'::jsonb, true, 32),
  ('KNOW-17', 'KNOWLEDGE', 'Туалет для кошки', 'Разберись в типах туалетов и аксессуарах: лопатки, пакеты, дезодоранты, сетки.', 'Продавец предлагает туалет и аксессуары под тип наполнителя и кошку.', 'туалеты/аксессуары', 'При выборе туалета уточни размер кошки, формат текущего лотка, тип наполнителя и что неудобно владельцу сейчас. Сравни открытые и закрытые модели по размерам, конструкции и инструкции производителя, а не по универсальным обещаниям. Затем предложи совместимые аксессуары: лопатку, пакеты и другие позиции, которые реально подходят выбранному лотку и наполнителю.', '["Что нужно узнать о кошке и текущем лотке перед подбором нового туалета?","По каким данным сравниваем открытые и закрытые модели?","Как подобрать аксессуары так, чтобы они были совместимы с выбранным лотком и наполнителем?"]'::jsonb, true, 33),
  ('KNOW-18', 'KNOWLEDGE', 'Как изучать новый товар', 'Изучи новинку ассортимента: назначение, отличия, кому подходит, какие вопросы задавать.', 'Продавец может рассказать о новинке и предложить её подходящему покупателю.', 'продажи', 'Для изучения берём конкретную новинку из текущего ассортимента. Сначала читаем упаковку и официальный материал производителя, затем фиксируем назначение, 2–3 подтверждённых отличия и вопросы, которые помогут понять потребность покупателя. Свойства не додумываем и не обещаем эффект, которого нет в источнике.', '["Где проверить свойства нового товара?","Какие 2–3 подтверждённых отличия у выбранной новинки?","Какому покупателю её можно предложить и какой вопрос нужно задать сначала?"]'::jsonb, true, 34),
  ('KNOW-19', 'KNOWLEDGE', 'Выявление потребности', 'Освой короткую схему вопросов перед подбором товара.', 'Продавец сначала выясняет ситуацию покупателя и только потом предлагает товар.', 'продажи', 'Перед подбором выясни минимум три вещи: для какого питомца покупка, какая задача у владельца и что уже использовали раньше. Для кормов и средств ухода дополнительно уточняй возраст и другие параметры, которые прямо указаны производителем как важные для выбора. После этого предложи 1–2 подходящих варианта и коротко объясни различие.', '["Какие три базовых вопроса нужно задать до предложения товара?","Почему не стоит начинать консультацию сразу с конкретного бренда?","Как объяснить покупателю разницу между двумя подходящими вариантами?"]'::jsonb, true, 35),
  ('KNOW-20', 'KNOWLEDGE', 'Границы консультации', 'Научись отличать товарную консультацию от ветеринарного назначения.', 'Продавец уверенно консультирует по товару и не выходит за границы своей роли.', 'продажи', 'Мы можем объяснить назначение товара, состав и способ применения по упаковке или официальным материалам производителя, сравнить варианты и помочь найти нужную позицию. Мы не ставим диагноз, не назначаем лечение и не меняем назначения ветеринарного врача. Если покупатель описывает симптомы или просит подобрать лечение, рекомендуем обратиться к ветеринарному специалисту.', '["Что продавец может объяснить покупателю самостоятельно?","Какие вопросы нужно передать ветеринарному специалисту?","Как вежливо ответить покупателю, который просит подобрать лечение?"]'::jsonb, true, 36),
  ('KNOW-21', 'KNOWLEDGE', 'Бонусная система «Миски»', 'Выучи правила бонусной карты и умей объяснить их покупателю без путаницы.', 'Продавец правильно объясняет выдачу карты, начисление, срок бонусов и лимит списания.', 'продажи', 'Карта «Миски» выдаётся при покупке от 2 000 ₽. На покупки начисляется 5% бонусами. Бонусы действуют 3 месяца, а при следующей покупке ими можно оплатить до 15% суммы чека. Перед расчётом коротко напомни покупателю о карте и доступных бонусах, если это уместно.', '["От какой суммы выдаётся карта «Миски»?","Сколько бонусов начисляется и как долго они действуют?","Какую часть следующей покупки можно оплатить бонусами?"]'::jsonb, true, 37),
  ('KNOW-22', 'KNOWLEDGE', 'Craftia', 'Изучи, как презентовать корма Craftia только по подтверждённым свойствам бренда и конкретной упаковки.', 'Продавец называет подтверждённые особенности Craftia и подбирает конкретный рацион по данным производителя.', 'корма', 'Официальный сайт Craftia относит бренд к ультрапремиальным кормам для собак и кошек на основе свежего мяса и указывает отсутствие эмульгаторов, ароматизаторов, красителей и консервантов, а также технологию Nutribiome. При продаже сначала уточни вид и возраст питомца, затем сверяй рецепт, назначение и норму кормления конкретной упаковки. Не переноси свойства одного рецепта на всю линейку. Источник для обучения: craftia.pet.', '["Какие особенности бренда Craftia прямо заявлены на официальном сайте?","Что нужно проверить на конкретной упаковке перед рекомендацией?","Почему нельзя переносить свойства одного рецепта на всю линейку?"]'::jsonb, true, 38),
  ('KNOW-23', 'KNOWLEDGE', 'Bambini Pets', 'Изучи ассортимент Bambini Pets для грызунов, кроликов и птиц и научись начинать подбор с вида питомца.', 'Продавец понимает, для каких питомцев предназначен бренд, и подбирает товар по виду животного и назначению.', 'игрушки', 'Bambini Pets — бренд товаров для грызунов, кроликов и птиц. На официальном сайте представлены корма, лакомства, наполнители, домики и гамаки, минеральные камни и сепия, а также игрушки для грызунов, кроликов и птиц. При подборе сначала уточни вид питомца и назначение товара, затем проверь материал, размер и ограничения конкретного изделия на упаковке. Источник для обучения: bambinipets.ru.', '["Для каких групп питомцев предназначен Bambini Pets?","Какие категории товаров есть у бренда по официальному сайту?","Что нужно проверить у конкретной игрушки или аксессуара перед продажей?"]'::jsonb, true, 39),
  ('KNOW-24', 'KNOWLEDGE', 'Ферма кота Фёдора', 'Изучи основные категории бренда и как отличать товары для котят, взрослых и стерилизованных кошек.', 'Продавец ориентируется в категориях бренда и подбирает конкретный продукт по возрасту и назначению.', 'корма', 'Официальный сайт «Фермы кота Фёдора» показывает сухие и влажные корма, а также лакомства для кошек и котят. В ассортименте есть продукты для взрослых и стерилизованных кошек и отдельные продукты для котят. При консультации не говори о бренде в целом вместо конкретного товара: проверь возраст, назначение, полнорационность и норму кормления на упаковке. Источник для обучения: catfedor.ru.', '["Какие основные категории товаров есть у «Фермы кота Фёдора»?","Для каких возрастных или физиологических групп есть отдельные продукты?","Какие данные нужно проверить на упаковке конкретного корма?"]'::jsonb, true, 40),
  ('KNOW-25', 'KNOWLEDGE', 'Japan Premium Pet', 'Изучи японские товары ухода и гигиены из ассортимента Premium Pet и правила безопасной консультации.', 'Продавец различает назначение средств ухода и объясняет применение по официальной карточке конкретного товара.', 'уход', 'Официальный магазин Premium Pet представляет японские товары для груминга, гигиены, кожи и шерсти, зубов, ушей, глаз, а также наполнители и другие категории. У конкретных средств различаются зона применения, вид животного, формат и способ использования. Поэтому консультируй только по официальной карточке и упаковке конкретного товара; не превращай гигиеническое средство в обещание лечения. Источник для обучения: premium-pet.com.', '["Какие группы товаров Japan Premium Pet представлены на официальном сайте Premium Pet?","Что нужно сверить у конкретного средства ухода перед продажей?","Почему нельзя обещать лечебный эффект гигиенического товара без такого назначения производителя?"]'::jsonb, true, 41),
  ('SALE-01', 'SALES', 'Наполнитель + дополнение', 'В каждом чеке с наполнителем предлагай логичное дополнение: лопатку, пакеты, дезодорант, совок.', 'В смене минимум 2 чека с наполнителем дополнены полезным товаром.', 'продажи', NULL, NULL, true, 42),
  ('SALE-02', 'SALES', 'Корм + дополнение', 'При продаже корма предлагай полезное дополнение: лакомство, влажный корм, мерный стакан, контейнер для хранения.', 'В смене минимум 2 кормовых чека дополнены сопутствующим товаром.', 'продажи', NULL, NULL, true, 43),
  ('SALE-03', 'SALES', 'Новый питомец', 'Когда покупатель говорит, что только что завёл питомца, собери базовый набор: корм, туалет/пелёнки, лакомство, игрушку, средство от паразитов по возрасту.', 'Умение собрать стартовый набор и объяснить, зачем нужна каждая позиция.', 'продажи', NULL, NULL, true, 44),
  ('SALE-04', 'SALES', 'Шампунь + уход', 'При продаже шампуня предлагай расчёску, полотенце или средство для ушей — по типу шерсти животного.', 'Каждый второй чек со шампунем дополнен товаром для ухода.', 'продажи', NULL, NULL, true, 45),
  ('SALE-05', 'SALES', 'Туалет комплектом', 'Продавай туалет комплектом: туалет + лопатка + пакеты + (при необходимости) сетка или дезодорант.', 'Умение предложить комплект одним предложением, а не списком позиций.', 'продажи', NULL, NULL, true, 46),
  ('SALE-06', 'SALES', 'Игрушка по потребности', 'Прежде чем предлагать игрушку, задай 1–2 вопроса о питомце (возраст, активность, что уже есть дома) и предложь подходящий вариант.', 'Покупатель уходит с игрушкой, подходящей его питомцу, а не случайной.', 'продажи', NULL, NULL, true, 47),
  ('SALE-07', 'SALES', 'Возражение «дорого»', 'Отработай ответ на возражение «дорого»: сравнение по составу/расходу, альтернатива дешевле, акция, или честное «это лучший вариант под задачу».', 'Продавец не теряется на возражении и предлагает осмысленный вариант, а не скидку.', 'продажи', NULL, NULL, true, 48),
  ('SALE-08', 'SALES', 'Три вопроса покупателю', 'Перед подбором товара задай покупателю минимум три уточняющих вопроса о питомце и ситуации.', 'Подбор строится на потребности: в смене минимум 3 диалога начинаются с уточняющих вопросов.', 'продажи', NULL, NULL, true, 49),
  ('SALE-09', 'SALES', 'Знаю альтернативу', 'Выучи сегодняшний топ-5 товаров категории и по каждому — одну дешевле и одну дороже альтернативу.', 'Продавец может предложить альтернативу без уточнения у коллег.', 'продажи', NULL, NULL, true, 50),
  ('SALE-10', 'SALES', 'Комплексная консультация', 'Отработай схему комплексной продажи: потребность → подбор → объяснение → полезное дополнение → следующий шаг для покупателя.', 'Консультация завершается дополнением к основной покупке в половине случаев.', 'продажи', NULL, NULL, true, 51)
